    import copy
    result = copy.deepcopy(record)

    # Extract secrets and sort by value length (longest first) to handle overlaps
    secrets = result.get('secrets', [])
    secret_map = []
    for secret in secrets:
        if 'value' in secret and secret['value']:
            secret_map.append({
                'name': secret['name'],
                'value': secret['value']
            })

    # Sort by value length descending so longer secrets are replaced first
    secret_map.sort(key=lambda x: len(x['value']), reverse=True)

    # Redact the secret values themselves
    for secret in result.get('secrets', []):
        if 'value' in secret and secret['value']:
            secret['value'] = f"<redacted:{secret['name']}>"

    # Recursively redact all string values in the record
    def redact_value(obj):
        if isinstance(obj, str):
            # Apply redactions in order (longest first)
            redacted = obj
            for secret in secret_map:
                redacted = redacted.replace(secret['value'], f"<redacted:{secret['name']}>")
            return redacted
        elif isinstance(obj, dict):
            # Don't redact inside secret_ref objects
            if obj.get('secret_ref') is not None:
                return obj
            # Recursively redact all values in the dict
            return {k: redact_value(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            # Recursively redact all items in the list
            return [redact_value(item) for item in obj]
        else:
            # Return other types unchanged (numbers, booleans, None, etc.)
            return obj

    # Apply redaction to all top-level values except 'secrets' (already handled)
    for key in result:
        if key != 'secrets':
            result[key] = redact_value(result[key])

    # Add redaction policy
    result['redaction_policy'] = 'redaction-contract/1'

    return result
